// Builds firestore.rules from src/data/students.json and src/data/teachers.json.
// Run it after adding or changing students:  npm run rules
import fs from 'fs';

const students = JSON.parse(fs.readFileSync('src/data/students.json', 'utf8'));
const teachers = JSON.parse(fs.readFileSync('src/data/teachers.json', 'utf8'));

const studentMap = students
  .filter(s => s.githubId)
  .map(s => `        '${s.githubId}': '${s.id}'`)
  .join(',\n');
const teacherList = teachers.map(id => `'${id}'`).join(', ');

const rules = `rules_version = '2';

// GENERATED by scripts/generate-firestore-rules.mjs. Do not edit by hand:
// update students.json / teachers.json and run \`npm run rules\`.
service cloud.firestore {
  match /databases/{database}/documents {
    function githubId() {
      return request.auth != null && 'github.com' in request.auth.token.firebase.identities
        ? request.auth.token.firebase.identities['github.com'][0]
        : '';
    }

    function isTeacher() {
      return githubId() in [${teacherList}];
    }

    // GitHub id -> student id in students.json
    function myStudentId() {
      return {
${studentMap}
      }.get(githubId(), '');
    }

    function isStudent() {
      return myStudentId() != '';
    }

    function ownsRecord() {
      return isStudent() && resource.data.studentId == myStudentId();
    }

    match /tasks/{taskId} {
      allow read: if isTeacher() || isStudent();
      allow write: if isTeacher();
    }

    match /attendance/{docId} {
      allow read: if isTeacher() || ownsRecord();
      allow write: if isTeacher();
    }

    // Grade ids are "<studentId>_Sprint<n>": a student may also read their own
    // ids before the document exists, which ownsRecord() alone can't allow
    match /grades/{docId} {
      allow read: if isTeacher() || ownsRecord() || (isStudent() && docId.matches(myStudentId() + '_Sprint[0-9]+'));
      allow write: if isTeacher();
    }

    match /students/{studentId} {
      allow read, write: if isTeacher();
    }

    match /followups/{studentId} {
      allow read, write: if isTeacher();
    }

    match /evaluations/{teamId} {
      allow read, write: if isTeacher();
    }

    // Public landing page data (which teams presented their demo); no grades or names
    match /public/{docId} {
      allow read: if true;
      allow write: if isTeacher();
    }
  }
}
`;

fs.writeFileSync('firestore.rules', rules);
console.log(`firestore.rules: ${students.filter(s => s.githubId).length} students, ${teachers.length} teacher(s)`);
